// Isolation test (OS-12) — construct CandidateLedger with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21, MF-22.)
import { describe, expect, it } from "vitest";
import { noSubject, refuse, type RecordHeight } from "../src/kernel/index.js";
import { CurrencyOrder, DeclarationLedger, IndependenceLedger, type Currency, type Unit } from "../src/catalog/index.js";
import {
  BOTTOM,
  CandidateLedger,
  CommitmentLedger,
  DrawContextLog,
  type CandidateLedgerInputs,
  type CandidateProposal,
  type InvalidationReader,
} from "../src/facts/index.js";
import { inMemoryRecord, type TestRecord } from "./catalog/in-memory-record.js";

const u = "u1" as Unit;
const order = new CurrencyOrder({ currencies: ["c0", "c1"] });
const [c0, c1] = order.currencies() as readonly [Currency, Currency];
const never: InvalidationReader = { isInvalidated: () => false };

/** A world where u is declared, licensed independent, has a commitment at c0, and was drawn. */
function world(): { inputs: CandidateLedgerInputs; record: TestRecord; at: RecordHeight; proposal: CandidateProposal } {
  const record = inMemoryRecord();
  const declarations = new DeclarationLedger({ record, levels: ["easy"] });
  declarations.declare(u, "easy", "HUMAN");
  const commitments = new CommitmentLedger({ record, invalidations: never });
  const independence = new IndependenceLedger({ record });
  independence.declareIndependence(u, true, "HUMAN");
  // R-41: k0 accepts a real candidate at c0 (BOTTOM, licensed), appended through a setup ledger.
  const h0 = record.noise();
  const draws = new DrawContextLog({ record, declarations });
  const ctx0 = draws.recordDraw(u, { colour: "red" }, h0, "setup", h0, "ENGINE");
  if (!("payload" in ctx0)) throw new Error("setup: the draw was refused");
  const setup = new CandidateLedger({
    record,
    commitments,
    currencies: order,
    independence,
    admission: { admit: () => "ADMIT" },
    signatures: { check: () => "VERIFIED" },
    ceiling: { admitsDraw: () => "WITHIN" },
  });
  const s0 = setup.appendCandidate({ context: ctx0, unit: u, currency: c0, condition: "setup", seed: "s", from: BOTTOM }, "sig", record.noise(), "ENGINE");
  if (!("payload" in s0)) throw new Error("setup: the candidate was refused");
  const k0 = commitments.commit(s0, "HUMAN");
  const h = record.noise();
  const context = draws.recordDraw(u, { colour: "red" }, h, "k", h, "ENGINE");
  if (!("payload" in context)) throw new Error("setup: the draw was refused");
  const inputs: CandidateLedgerInputs = {
    record,
    commitments,
    currencies: order,
    independence,
    admission: { admit: () => "ADMIT" },
    signatures: { check: () => "VERIFIED" },
    ceiling: { admitsDraw: () => "WITHIN" },
  };
  return { inputs, record, at: record.noise(), proposal: { context, unit: u, currency: c1, condition: "k", seed: "s", from: k0 } };
}
const bottomAtLeast = (p: CandidateProposal): CandidateProposal => ({ ...p, currency: c0, from: BOTTOM });

describe("CandidateLedger in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { inputs } = world();
    for (const missing of Object.keys(inputs)) {
      const partial = Object.fromEntries(Object.entries(inputs).filter(([k]) => k !== missing));
      expect(() => new CandidateLedger(partial as never), `constructed without ${missing}`).toThrow();
    }
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { inputs } = world();
    for (const slot of Object.keys(inputs)) {
      expect(() => new CandidateLedger({ ...inputs, [slot]: {} } as never), `${slot} was not checked`).toThrow();
    }
  });

  it("appendCandidate answers differently when record differs", () => {
    const one = world();
    const two = world();
    two.record.noise();
    const a = new CandidateLedger(one.inputs).appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    const b = new CandidateLedger(two.inputs).appendCandidate(two.proposal, "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  // Each side of a comparison comes from its OWN world, identical but for the one input varied,
  // so a draw context bound by side a cannot answer for side b (R-33).
  it("appendCandidate answers differently when admission differs", () => {
    const one = world();
    const two = world();
    const a = new CandidateLedger(one.inputs).appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    const b = new CandidateLedger({ ...two.inputs, admission: { admit: () => refuse("unreachable") } }).appendCandidate(two.proposal, "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("appendCandidate answers differently when signatures differs", () => {
    const one = world();
    const two = world();
    const a = new CandidateLedger({ ...one.inputs, signatures: { check: () => refuse("malformed-signature") } }).appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    const b = new CandidateLedger(two.inputs).appendCandidate(two.proposal, "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("appendCandidate answers differently when ceiling differs", () => {
    const one = world();
    const two = world();
    const a = new CandidateLedger({ ...one.inputs, ceiling: { admitsDraw: () => refuse("scope-exceeded") } }).appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    const b = new CandidateLedger(two.inputs).appendCandidate(two.proposal, "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("appendCandidate answers differently when commitments differs", () => {
    const one = world();
    const two = world();
    const a = new CandidateLedger(one.inputs).appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    const b = new CandidateLedger({ ...two.inputs, commitments: { effectiveCommitment: () => noSubject() } }).appendCandidate(two.proposal, "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("appendCandidate answers differently when currencies differs", () => {
    const one = world();
    const two = world();
    const a = new CandidateLedger(one.inputs).appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    const flat = { currencies: () => [c1], predecessors: () => [] };
    const b = new CandidateLedger({ ...two.inputs, currencies: flat }).appendCandidate(two.proposal, "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("appendCandidate answers differently when independence differs", () => {
    const one = world();
    const two = world();
    const a = new CandidateLedger(one.inputs).appendCandidate(bottomAtLeast(one.proposal), "sig", one.at, "ENGINE");
    const b = new CandidateLedger({ ...two.inputs, independence: { independenceAt: () => noSubject() } }).appendCandidate(bottomAtLeast(two.proposal), "sig", two.at, "ENGINE");
    expect(a).not.toEqual(b);
  });

  it("candidatesAsOf answers differently when record differs", () => {
    const one = world();
    const ledger = new CandidateLedger(one.inputs);
    const k = ledger.appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    if (!("payload" in k)) throw new Error("setup: the candidate was refused");
    const a = ledger.candidatesAsOf(u, c1, "k", k.at);
    const b = new CandidateLedger(world().inputs).candidatesAsOf(u, c1, "k", k.at);
    expect(a).not.toEqual(b);
  });

  it("derivedFrom answers differently when record differs", () => {
    const one = world();
    const ledger = new CandidateLedger(one.inputs);
    const k = ledger.appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    if (!("payload" in k) || !("payload" in one.proposal.from)) throw new Error("setup");
    const a = ledger.derivedFrom(one.proposal.from, k.at);
    const b = new CandidateLedger(world().inputs).derivedFrom(one.proposal.from, k.at);
    expect(a).not.toEqual(b);
  });

  it("countsAsOf answers differently when record differs", () => {
    const one = world();
    const ledger = new CandidateLedger(one.inputs);
    const k = ledger.appendCandidate(one.proposal, "sig", one.at, "ENGINE");
    if (!("payload" in k)) throw new Error("setup: the candidate was refused");
    const a = ledger.countsAsOf(u, k.at);
    const b = new CandidateLedger(world().inputs).countsAsOf(u, k.at);
    expect(a).not.toEqual(b);
  });

  it("countsAsOf answers differently when currencies differs", () => {
    const { inputs, at } = world();
    const a = new CandidateLedger(inputs).countsAsOf(u, at);
    const b = new CandidateLedger({ ...inputs, currencies: { currencies: () => [c0], predecessors: () => [] } }).countsAsOf(u, at);
    expect(a).not.toEqual(b);
  });
});
